package in.amanahpay.config;
import io.jsonwebtoken.Jwts;import io.jsonwebtoken.security.Keys;import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.*;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.web.SecurityFilterChain;import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;import java.util.Base64;import java.util.List;
@Configuration public class SecurityConfig {
 @Bean SecurityFilterChain filter(HttpSecurity http,@Value("${amanah.jwt-secret}")String secret)throws Exception{return http.csrf(c->c.disable()).cors(c->{}).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).exceptionHandling(e->e.authenticationEntryPoint((request,response,error)->response.sendError(HttpServletResponse.SC_UNAUTHORIZED))).authorizeHttpRequests(a->a.requestMatchers("/api/v1/auth/**","/api/v1/customer/auth/**","/api/v1/customer/link/*/otp/request","/api/v1/customer/otp/verify","/api/health","/actuator/health").permitAll().anyRequest().authenticated()).addFilterBefore(new TokenFilter(secret),UsernamePasswordAuthenticationFilter.class).build();}
 static class TokenFilter extends OncePerRequestFilter {final String secret;TokenFilter(String s){secret=s;}protected void doFilterInternal(HttpServletRequest r,HttpServletResponse w,FilterChain c)throws ServletException,IOException{String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{var p=Jwts.parser().verifyWith(Keys.hmacShaKeyFor(Base64.getDecoder().decode(secret))).build().parseSignedClaims(h.substring(7)).getPayload();r.setAttribute("amanah.userId",p.getSubject());r.setAttribute("amanah.role",p.get("role"));r.setAttribute("amanah.scope",p.get("scope"));r.setAttribute("amanah.planId",p.get("planId"));r.setAttribute("amanah.customerId",p.get("customerId"));r.setAttribute("amanah.customerAccountId",p.get("customerAccountId"));var auth=new UsernamePasswordAuthenticationToken(p.getSubject(),null,List.of(new SimpleGrantedAuthority("ROLE_"+p.get("role"))));SecurityContextHolder.getContext().setAuthentication(auth);}catch(Exception ignored){}c.doFilter(r,w);}}
}
